import type { Totals } from "../existing/invoice";
import { round } from "../existing/math";
import type { Line } from "../existing/types";

export function clientTotals(entries: Line[], percent: number): Totals {
  let net = 0;
  for (const entry of entries) {
    if (entry.quantity <= 0) {
      throw new Error(`invalid quantity for ${entry.sku}`);
    }
    net += entry.quantity * entry.unitPrice;
  }
  const tax = round(net * percent, 2);
  return { net: round(net, 2), tax, gross: round(net + tax, 2) };
}
